/* Thread 3 hero sprite - archetype: FLYTHROUGH, 72 frames, 6x12 grid, native ratio 16:9 */
.hero-sprite {
  aspect-ratio: 16 / 9;
  width: min(90vw, 1200px);
  height: auto;
  margin: 0 auto;
  background-image: url('sprite.webp');
  background-repeat: no-repeat;
  background-size: 600% 1200%; /* percentage, not px - required, see this project's own bleed-bug finding */
  background-position: 100% 100%; /* unconditional base state: the chosen fallback frame's grid cell (5,11), frame index 71 - per-archetype choice (src/archetypes.js), not always the last frame and NOT always "100% 100%" even when it is, since frameCount doesn't always fill the grid exactly */
}

@supports (animation-timeline: scroll()) {
  .hero-sprite {
    animation: hero-scrub-flythrough linear both;
    animation-timeline: scroll(root block);
  }
}

@keyframes hero-scrub-flythrough {
